'use client';

import React, { useMemo, useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import { useTexture } from '@react-three/drei';
import * as THREE from 'three';
import { globeVertexShader, globeFragmentShader } from './shaders/globeShaders';

function addBarycentricCoordinates(geometry: THREE.BufferGeometry) {
  // Ensure geometry is non-indexed so we can assign barycentric coordinates per triangle vertex
  let nonIndexedGeometry = geometry;
  if (geometry.index) {
    nonIndexedGeometry = geometry.toNonIndexed();
  }

  const count = nonIndexedGeometry.attributes.position.count;
  const barycentrics = [];

  for (let i = 0; i < count; i += 3) {
    barycentrics.push(1, 0, 0);
    barycentrics.push(0, 1, 0);
    barycentrics.push(0, 0, 1);
  }

  const baryAttr = new THREE.Float32BufferAttribute(barycentrics, 3);
  nonIndexedGeometry.setAttribute('barycentric', baryAttr);
  return nonIndexedGeometry;
}

export const Globe = () => {
  const meshRef = useRef<THREE.Mesh>(null);
  
  // Load textures
  const [displacementMap, textureMap] = useTexture([
    '/assets/textures/displacement.png',
    '/assets/textures/texture_vibrant_low_res.png',
  ]);

  useMemo(() => {
    displacementMap.wrapS = displacementMap.wrapT = THREE.RepeatWrapping;
    textureMap.wrapS = textureMap.wrapT = THREE.RepeatWrapping;
  }, [displacementMap, textureMap]);

  const geometry = useMemo(() => {
    let geom = new THREE.IcosahedronGeometry(3, 40);
    geom = addBarycentricCoordinates(geom) as THREE.IcosahedronGeometry; // Casting to keep type happy, though it returns BufferGeometry
    return geom;
  }, []);

  const uniforms = useMemo(
    () => ({
      uDisplacementMap: { value: displacementMap },
      uTexture: { value: textureMap },
      dispScale: { value: 1.0 },
      uLightDir: { value: new THREE.Vector3(1, 1, 1).normalize() },
      uCameraPos: { value: new THREE.Vector3() },
    }),
    [displacementMap, textureMap]
  );

  useFrame((state) => {
    if (meshRef.current) {
      const material = meshRef.current.material as THREE.ShaderMaterial;
      const t = state.clock.getElapsedTime() * 0.1; // Slow rotation

      const lightDir = new THREE.Vector3(
        Math.sin(t),
        Math.cos(t),
        Math.sin(t * 0.5)
      ).normalize();
      
      material.uniforms.uLightDir.value.copy(lightDir);
      material.uniforms.uCameraPos.value.copy(state.camera.position);
    }
  });

  return (
    <mesh ref={meshRef} geometry={geometry}>
      <shaderMaterial
        vertexShader={globeVertexShader}
        fragmentShader={globeFragmentShader}
        uniforms={uniforms}
      />
    </mesh>
  );
};
